"""
    Convert axial coordinate to its cubic equivalent.
    """
def axial_to_cubic(col: Any, slant: Any) -> object {
    x = col;
    z = slant;
    y = -x - z;
    return (x, y, z);
}

"""Return True if ``d[k,j] = 0`` for ``0 <= k < i``

    Here ``d`` is a bit matrix implemented as an array of integers.
    """
def zero_column(d: Any, j: Any, i: Any) -> object {
    s = 0;
    for k in range(i) {
        s |= d[k];
    }
    return ((s & (1 << j)) == 0);
}
